pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, uint256 withdrawAmount) public {
        // Bound amounts to avoid overflow on deposit sum, keeping the domain wide
        amount1 = bound(amount1, 0, type(uint128).max);
        amount2 = bound(amount2, 0, type(uint128).max);
        withdrawAmount = bound(withdrawAmount, 0, type(uint128).max);

        // Two depositors
        address actor1 = address(0x1000);
        address actor2 = address(0x2000);

        vm.deal(actor1, amount1);
        vm.deal(actor2, amount2);

        vm.startPrank(actor1);
        c.deposit{value: amount1}();
        vm.stopPrank();

        vm.startPrank(actor2);
        c.deposit{value: amount2}();
        vm.stopPrank();

        uint256 totalDeposited = amount1 + amount2;
        uint256 preContractBalance = address(c).balance;
        uint256 preBal1 = c.balances(actor1);
        uint256 preBal2 = c.balances(actor2);

        // Actor1 withdraws up to their balance, could be zero
        uint256 actor1Bal = c.balances(actor1);
        if (withdrawAmount > actor1Bal) {
            withdrawAmount = actor1Bal;
        }

        vm.prank(actor1);
        c.withdraw(withdrawAmount);

        uint256 postBal1 = c.balances(actor1);
        uint256 postBal2 = c.balances(actor2);
        uint256 postContractBalance = address(c).balance;

        // General invariant: contract balance + sum of all recorded balances == total deposited
        // This holds for the reference but the bug (balance updated after transfer) can cause
        // reentrancy-like divergence where recorded balance exceeds actual contract funds.
        assertTrue(postContractBalance + postBal1 + postBal2 == totalDeposited);
    }
}

