pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        // actor must not be the C contract itself to avoid selfdestruct-like edge cases
        vm.assume(actor != address(c));
        // cast caller to a payable address for vm.deal and prank
        address payable caller = payable(actor);
        // fund the caller with enough ETH to deposit and then withdraw
        vm.deal(caller, amount * 2);
        // deposit to give the caller a balance
        vm.prank(caller);
        c.deposit{value: amount}();
        // record contract balance before withdraw
        uint256 contractBalanceBefore = address(c).balance;
        // call withdraw
        vm.prank(caller);
        try c.withdraw(amount) {
            // withdraw succeeded
        } catch {
            // ignore reverts; we only test successful withdrawals
        }
        uint256 contractBalanceAfter = address(c).balance;
        // For a successful withdraw, the contract balance must decrease by exactly the withdrawn amount.
        // The buggy version deducts the internal balance before the transfer, but if the transfer fails
        // (e.g., due to a malicious fallback that uses up all gas), the contract's ETH balance stays the same
        // while the internal balance is already reduced, causing a mismatch.
        // We assert that if withdraw did NOT revert, the contract balance decreased by amount.
        // Note: We cannot directly observe a revert boolean from try/catch here without a flag,
        // but we can check that the contract balance decreased by exactly the amount if the internal balance
        // was reduced. Since the reference version transfers first, a revert would not change balances at all.
        // The buggy version changes the internal balance BEFORE transfer, so a failed transfer
        // leads to contractBalanceAfter == contractBalanceBefore while internal balance is less.
        // To capture this, we assert that if internal balance is reduced, the contract balance must reflect the transfer.
        // Obtain caller's current internal balance via a public getter (balances is public -> auto-generated getter)
        uint256 callerBalance = c.balances(caller);
        // If withdraw succeeded, callerBalance should be amount less than deposit (i.e., amount - amount = 0).
        // If transfer failed in buggy version, callerBalance = 0 but contractBalance unchanged.
        if (callerBalance == 0) {
            // withdraw must have reduced internal balance by amount. Then contract balance must have decreased by amount.
            assertTrue(contractBalanceAfter == contractBalanceBefore - amount);
        } else {
            // If internal balance not reduced (e.g., revert before deduction), nothing changed.
            assertTrue(contractBalanceAfter == contractBalanceBefore && callerBalance == amount);
        }
    }
}

